mapper.select:
SELECT
    COUNT(*) AS joined,
    COUNT(*) FILTER (WHERE entry.offered_at IS NOT NULL) AS offered,
    COUNT(*) FILTER (WHERE entry.status = 'FULFILLED') AS fulfilled,
    COUNT(*) FILTER (WHERE entry.status = 'EXPIRED') AS expired,
    COUNT(*) FILTER (WHERE entry.status = 'CANCELLED') AS cancelled
FROM waitlist_entries entry
WHERE entry.created_at >= #{from}
  AND entry.created_at < #{to}
  AND entry.event_id = #{eventId}
